//! The `ReportGenerated` record of a generated output. The rest of the
//! `Report` envelope lives in `fstp-report-core`.

use fstp_domain::id::AccountId;
use fstp_report_core::{ReportId, ReportRecord};

use crate::output::Output;

/// The `ReportGenerated` record of `output`, generated by `by`.
pub fn generated(report: ReportId, output: &Output, by: AccountId) -> ReportRecord {
    ReportRecord::Generated {
        report,
        kind: output.kind,
        scope: output.scope,
        snapshot: output.snapshot,
        template: output.template.to_owned(),
        document: output.digest,
        by,
    }
}
